use axum::{body::Body, http::Request, routing::get_service, Router};
use tower::ServiceExt;
use tower_http::services::ServeDir;

fn main() {
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(async {
            let routes_static = Router::new().nest_service("/", get_service(ServeDir::new("./")));
            let routes_all = Router::new().fallback_service(routes_static);
            let response = routes_all
                .oneshot(Request::builder().uri("/axum/src/lib.rs").body(Body::empty()).unwrap())
                .await
                .unwrap();
            assert_eq!(response.status(), axum::http::StatusCode::OK);
        });
}
